  IntPtr WndProc(IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled) {
    if (msg == WM_HOTKEY) {
      if (wParam.ToInt32() == HotkeyTracker && User != null) ToggleTrackerSystem();
      if (wParam.ToInt32() == HotkeyMode && User != null) ToggleMode();
      if (wParam.ToInt32() == HotkeyMin && User != null) ToggleDroidArea();
      if (wParam.ToInt32() == HotkeySearch && User != null) ToggleSearchMode();
      if (wParam.ToInt32() == HotkeySettings) ShowUiSettings();
      handled = true;
    }
    return IntPtr.Zero;
  }

